const toggle = off === 0 ? '📅 ' + other.name + ' →' : '← 📅 ' + other.name;
const reply = bad
  ? 'Ներողություն, օրացույցում սխալ գրառում կա, և չեմ կարող ստուգել ազատ ժամերը։ Փորձեք ավելի ուշ։'
