    : visit + '\n\nՑավոք, ' + cur.name + 'ին ազատ ժամ չկա Ձեր այցի համար։\nՍեղմեք «' + toggle + '»՝ ' + other.name + 'ի օրերը տեսնելու համար, կամ «⬅️ Հետ»՝ այլ ամիս ընտրելու համար։';
// Up to 6 rows of 4 date buttons; the right keyboard size is picked by the number of rows.
const labels = [];
for (let i = 0; i < 24; i++) labels.push(days[i] ? days[i].label : '·');
return [{ json: { pick_month: false, reply, labels, has_dates: days.length > 0, days, rows: Math.max(1, Math.ceil(days.length / 4)), toggle, month_key: cur.key, month_labels: [] } }];

// Upcoming active bookings of this patient (max 5), one item per booking card.
const r = $('Route').first().json;
const docs = {};
$('Load doctors').all().forEach(i => { if (i.json && i.json.doctor_key) docs[i.json.doctor_key] = i.json.doctor_name; });
const now = Date.now();
const rows = $('Load my bookings').all().map(i => i.json)
  .filter(x => x && x.request_id && ['approved', 'pending'].includes(x.status) && Date.parse(x.slot_start) > now)
  .sort((a, b) => Date.parse(a.slot_start) - Date.parse(b.slot_start))
  .slice(0, 5);
if (!rows.length) return [{ json: { has: false, chat_id: r.chat_id } }];
return rows.map(x => ({ json: { has: true, chat_id: r.chat_id, request_id: x.request_id,
  text: '📅 ' + x.slot_start.slice(0, 10) + ', ' + x.slot_start.slice(11, 16) + ' (Երևան)\nԲժիշկ՝ ' + (docs[x.doctor_key] || '') + '\nԾառայություն՝ ' + (x.service || '—') + '\nԱյցելու՝ ' + (x.patient_full_name || x.patient_name || '—') + '\nԿարգավիճակ՝ ' + (x.status === 'approved' ? '✅ Հաստատված' : '⏳ Սպասում է բժշկի հաստատմանը') + '\nՀայտ՝ ' + x.request_id } }));

// Day-before reminder: 24h..2h before the visit (only if booked more than ~26h ahead).
// Two-hour reminder: within 2h of the visit (only if booked more than 2h ahead).
const docs = {};
$('Load doctors for reminders').all().forEach(i => { if (i.json && i.json.doctor_key) docs[i.json.doctor_key] = i.json.doctor_name; });
const now = Date.now(), H = 3600e3;
const ymd = ms => new Date(ms + 4 * H).toISOString().slice(0, 10);
const out = [];
for (const x of $('Load confirmed bookings').all().map(i => i.json)) {
  if (!x || !x.request_id || x.status !== 'approved') continue;
  const start = Date.parse(x.slot_start);
  if (!(start > now)) continue;
  const lead = start - now;
  const ahead = start - (Date.parse(x.createdAt) || 0);
  const sent24 = x.reminder_24h_sent === true, sent2 = x.reminder_2h_sent === true;
  let kind = '';
